WITH открытая AS (SELECT vs.version FROM version_state vs JOIN project_plan_versions pv ON pv.project_id = vs.project_id AND pv.id = vs.version WHERE vs.project_id = $1 AND vs.state = 'open' LIMIT 1), новый AS (INSERT INTO project_plan_milestones (project_id, id, version_id, ord, title) SELECT $1, 'M9PROBE', о.version, 9999, 'подсадка самотеста' FROM открытая о WHERE NOT EXISTS (SELECT 1 FROM project_plan_milestones m WHERE m.project_id = $1 AND m.version_id = о.version) RETURNING id), м AS (SELECT id FROM новый UNION ALL SELECT m.id FROM project_plan_milestones m JOIN открытая о ON m.version_id = о.version WHERE m.project_id = $1 UNION ALL SELECT m.id FROM project_plan_milestones m WHERE m.project_id = $1 AND NOT EXISTS (SELECT 1 FROM открытая) LIMIT 1) INSERT INTO project_plan_tasks(project_id, id, milestone_id, ord, title, size, state, kind, origin) SELECT $1, 'M9-TVPROBE', (SELECT id FROM м LIMIT 1), 9993, 'подсадка самотеста', 'S', 'not_started', 'dev', 'declared' WHERE EXISTS (SELECT 1 FROM м)
